<?php

namespace Database\Seeders;

use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\DB;

class PrivacyPolicySeeder extends Seeder
{
    public function run(): void
    {
        $sections = [
            ['INTRODUCTION', 'At UniAds, we are committed to protecting your privacy and ensuring the security of your personal information. This Privacy Policy explains how we collect, use, and safeguard your data when you interact with our platform. By accessing or using UniAds, you agree to the terms outlined in this Privacy Policy.\r\n\r\n𝟏. 𝐏𝐮𝐫𝐩𝐨𝐬𝐞 𝐨𝐟 𝐭𝐡𝐞 𝐏𝐫𝐢𝐯𝐚𝐜𝐲 𝐏𝐨𝐥𝐢𝐜𝐲\r\n     ● Clearly explain what types of information we collect from users and institutions.\r\n     ● Outline how we use, store, and share that information.\r\n     ● Describe the rights and choices you have regarding your personal data.\r\n     ● Ensure transparency and compliance with applicable data protection laws.\r\n\r\n𝟐. 𝐖𝐡𝐨 𝐖𝐞 𝐀𝐫𝐞 (𝐔𝐧𝐢𝐀𝐝𝐬 𝐎𝐯𝐞𝐫𝐯𝐢𝐞𝐰)\r\nUniAds is an online platform designed to connect students with higher education institutions across Sri Lanka. Our mission is to make it easier for students to explore degree, diploma, and postgraduate programs, while enabling institutions to share information about their courses, events, and updates.\r\nWe provide features such as course listings, search and filtering, institute dashboards, and subscription-based services for premium institutes.\r\n\r\n𝟑. 𝐒𝐜𝐨𝐩𝐞 𝐨𝐟 𝐭𝐡𝐞 𝐏𝐨𝐥𝐢𝐜𝐲\r\n● All users who access or interact with the UniAds website and services.\r\n● Educational institutions and their representatives who manage profiles on UniAds.\r\n● Any third parties who interact with UniAds through integrations or linked services.\r\n\r\n𝗧𝗵𝗶𝘀 𝗣𝗼𝗹𝗶𝗰𝘆 𝗱𝗼𝗲𝘀 𝗻𝗼𝘁 𝗰𝗼𝘃𝗲𝗿 𝘁𝗵𝗶𝗿𝗱-𝗽𝗮𝗿𝘁𝘆 𝘄𝗲𝗯𝘀𝗶𝘁𝗲𝘀, 𝘀𝗲𝗿𝘃𝗶𝗰𝗲𝘀, 𝗼𝗿 𝗮𝗽𝗽𝗹𝗶𝗰𝗮𝘁𝗶𝗼𝗻𝘀 𝘁𝗵𝗮𝘁 𝗺𝗮𝘆 𝗯𝗲 𝗹𝗶𝗻𝗸𝗲𝗱 𝘁𝗵𝗿𝗼𝘂𝗴𝗵 𝗨𝗻𝗶𝗔𝗱𝘀. 𝗪𝗲 𝗲𝗻𝗰𝗼𝘂𝗿𝗮𝗴𝗲 𝘆𝗼𝘂 𝘁𝗼 𝗿𝗲𝘃𝗶𝗲𝘄 𝘁𝗵𝗲 𝗽𝗿𝗶𝘃𝗮𝗰𝘆 𝗽𝗼𝗹𝗶𝗰𝗶𝗲𝘀 𝗼𝗳 𝘁𝗵𝗼𝘀𝗲 𝗲𝘅𝘁𝗲𝗿𝗻𝗮𝗹 𝘀𝗲𝗿𝘃𝗶𝗰𝗲𝘀 𝘀𝗲𝗽𝗮𝗿𝗮𝘁𝗲𝗹𝘆.', 1],
            ['INFORMATION WE COLLECT', 'To provide the best possible experience on UniAds, we collect certain types of information from institutions and users. This information helps us operate the platform, ensure secure payments, improve features, and provide transparency between institutions and students. Below is a detailed breakdown of the data we collect and why.\r\n\r\n𝟏. 𝐀𝐜𝐜𝐨𝐮𝐧𝐭 𝐑𝐞𝐠𝐢𝐬𝐭𝐫𝐚𝐭𝐢𝐨𝐧 𝐚𝐧𝐝 𝐈𝐧𝐬𝐭𝐢𝐭𝐮𝐭𝐞 𝐃𝐞𝐭𝐚𝐢𝐥𝐬\r\nWhen an educational institute or student registers with UniAds, we collect essential account details to create and manage their profile. This information ensures that institutions are properly verified and can be presented accurately to students. Students benefit by being able to trust the legitimacy of the institutes they discover through UniAds.\r\nThis typically includes:\r\n● 𝐈𝐧𝐬𝐭𝐢𝐭𝐮𝐭𝐞 𝐧𝐚𝐦𝐞, 𝐞𝐦𝐚𝐢𝐥 𝐚𝐝𝐝𝐫𝐞𝐬𝐬, 𝐚𝐧𝐝 𝐜𝐨𝐧𝐭𝐚𝐜𝐭 𝐧𝐮𝐦𝐛𝐞𝐫 for identification and communication.\r\n● 𝐆𝐨𝐯𝐞𝐫𝐧𝐦𝐞𝐧𝐭 𝐫𝐞𝐠𝐢𝐬𝐭𝐫𝐚𝐭𝐢𝐨𝐧 𝐧𝐮𝐦𝐛𝐞𝐫 to verify the authenticity of the institution.\r\n● 𝐏𝐫𝐨𝐟𝐢𝐥𝐞 𝐚𝐧𝐝 𝐜𝐨𝐯𝐞𝐫 𝐩𝐡𝐨𝐭𝐨𝐬, 𝐛𝐢𝐨, 𝐚𝐧𝐝 𝐰𝐞𝐛𝐬𝐢𝐭𝐞 𝐥𝐢𝐧𝐤𝐬 to represent the institution’s brand.\r\n● 𝐋𝐨𝐜𝐚𝐭𝐢𝐨𝐧 𝐝𝐞𝐭𝐚𝐢𝐥𝐬 (𝐬𝐮𝐜𝐡 𝐚𝐬 𝐜𝐢𝐭𝐲 𝐨𝐫 𝐫𝐞𝐠𝐢𝐨𝐧) to allow students to filter and discover institutes easily.\r\n\r\n𝟐. 𝐏𝐚𝐲𝐦𝐞𝐧𝐭 𝐚𝐧𝐝 𝐁𝐢𝐥𝐥𝐢𝐧𝐠 𝐈𝐧𝐟𝐨𝐫𝐦𝐚𝐭𝐢𝐨𝐧\r\nFor institutes that subscribe to 𝐩𝐫𝐞𝐦𝐢𝐮𝐦 𝐩𝐥𝐚𝐧𝐬, we securely collect and process payment details through our payment gateway partner. We do not store full payment details on our servers. We only retain non-sensitive references such as subscription ID, plan type, and payment status. This allows us to manage premium features, enforce trial usage rules, and prevent unpaid access.\r\nThis handles:\r\n● 𝐂𝐫𝐞𝐝𝐢𝐭 𝐨𝐫 𝐝𝐞𝐛𝐢𝐭 𝐜𝐚𝐫𝐝 𝐢𝐧𝐟𝐨𝐫𝐦𝐚𝐭𝐢𝐨𝐧 for subscription payments.\r\n● 𝐁𝐢𝐥𝐥𝐢𝐧𝐠 𝐚𝐝𝐝𝐫𝐞𝐬𝐬 𝐚𝐧𝐝 𝐜𝐨𝐧𝐭𝐚𝐜𝐭 𝐢𝐧𝐟𝐨𝐫𝐦𝐚𝐭𝐢𝐨𝐧 required for invoices and compliance.\r\n● 𝐓𝐫𝐚𝐧𝐬𝐚𝐜𝐭𝐢𝐨𝐧 𝐡𝐢𝐬𝐭𝐨𝐫𝐲 𝐚𝐧𝐝 𝐬𝐮𝐛𝐬𝐜𝐫𝐢𝐩𝐭𝐢𝐨𝐧 𝐬𝐭𝐚𝐭𝐮𝐬 (e.g., active, cancelled, expired).\r\n\r\n𝟑. 𝐂𝐨𝐧𝐭𝐞𝐧𝐭 𝐔𝐩𝐥𝐨𝐚𝐝𝐬\r\nInstitutes can create and share content on UniAds, and we store this data to deliver some services. This content remains visible to users according to the institute’s settings, and is linked to the institute’s account. We may also analyze content engagement (e.g., views, applications, reviews) to provide institutes with insights through analytics dashboards.\r\nContents:\r\n● 𝐏𝐨𝐬𝐭𝐬: Announcements of new courses, degree programs, or updates.\r\n● 𝐄𝐯𝐞𝐧𝐭𝐬: Upcoming university events, open days, or webinars.\r\n● 𝐑𝐞𝐯𝐢𝐞𝐰𝐬 𝐚𝐧𝐝 𝐫𝐚𝐭𝐢𝐧𝐠𝐬: Feedback provided by students about institutions.\r\n\r\n𝟒. 𝐋𝐨𝐠 𝐃𝐚𝐭𝐚\r\nLike most platforms, UniAds automatically collects technical log information when users interact with the platform. We use this information to detect suspicious activity, improve site speed, troubleshoot errors, and enhance the user experience across devices.\r\nThis includes:\r\n● 𝐈𝐏 𝐚𝐝𝐝𝐫𝐞𝐬𝐬 and approximate location (used for security and fraud prevention).\r\n● 𝐁𝐫𝐨𝐰𝐬𝐞𝐫 𝐭𝐲𝐩𝐞 𝐚𝐧𝐝 𝐯𝐞𝐫𝐬𝐢𝐨𝐧 to optimize site performance.\r\n● 𝐃𝐞𝐯𝐢𝐜𝐞 𝐢𝐧𝐟𝐨𝐫𝐦𝐚𝐭𝐢𝐨𝐧 (desktop, mobile, OS version).\r\n● 𝐔𝐬𝐚𝐠𝐞 𝐝𝐚𝐭𝐚 such as pages viewed, search queries, and actions performed.\r\n\r\n𝟓. 𝐂𝐨𝐨𝐤𝐢𝐞𝐬 𝐚𝐧𝐝 𝐓𝐫𝐚𝐜𝐤𝐢𝐧𝐠\r\nUniAds uses cookies and similar technologies to personalize and improve the platform. Users can manage or disable cookies in their browser, but certain features (like staying logged in) may not work properly without them.\r\nThese include:\r\n● 𝐒𝐞𝐬𝐬𝐢𝐨𝐧 𝐜𝐨𝐨𝐤𝐢𝐞𝐬 to keep users logged in securely.\r\n● 𝐀𝐧𝐚𝐥𝐲𝐭𝐢𝐜𝐬 𝐜𝐨𝐨𝐤𝐢𝐞𝐬 (e.g., Google Analytics) to track user engagement and improve our services.\r\n● 𝐒𝐞𝐜𝐮𝐫𝐢𝐭𝐲 𝐜𝐨𝐨𝐤𝐢𝐞𝐬 to prevent fraud and protect user accounts.', 2],
            ['HOW WE USE YOUR INFORMATION', 'At UniAds, the information we collect is essential for running our services effectively, supporting institutions, and making the student experience seamless. We use your data in several ways to balance convenience, security, and transparency.\r\n\r\n𝟏. 𝐀𝐜𝐜𝐨𝐮𝐧𝐭 𝐌𝐚𝐧𝐚𝐠𝐞𝐦𝐞𝐧𝐭 𝐚𝐧𝐝 𝐀𝐮𝐭𝐡𝐞𝐧𝐭𝐢𝐜𝐚𝐭𝐢𝐨𝐧\r\nYour account details are primarily used to create and maintain your profile on UniAds. For institutes, this includes verifying registration information and allowing authorized representatives to manage their profiles. For students, it ensures secure login sessions and access to features such as course searches, saved items, and communication with institutions. By doing so, we safeguard the integrity of the platform and ensure that only genuine users and verified institutions can interact.\r\n\r\n𝟐. 𝐏𝐚𝐲𝐦𝐞𝐧𝐭 𝐚𝐧𝐝 𝐒𝐮𝐛𝐬𝐜𝐫𝐢𝐩𝐭𝐢𝐨𝐧 𝐏𝐫𝐨𝐜𝐞𝐬𝐬𝐢𝐧𝐠\r\nFor premium accounts, UniAds relies on our payment gateway partner to process payments. We do not store sensitive card details ourselves. Instead, Stripe manages all financial transactions securely, while we keep limited data such as:\r\n● Subscription plan details (monthly or annual)\r\n● Status of the subscription (trial, active, expired, or canceled)\r\n● Stripe’s unique subscription reference ID\r\n\r\n𝟑. 𝐂𝐨𝐦𝐦𝐮𝐧𝐢𝐜𝐚𝐭𝐢𝐨𝐧 𝐁𝐞𝐭𝐰𝐞𝐞𝐧 𝐔𝐬𝐞𝐫𝐬 𝐚𝐧𝐝 𝐈𝐧𝐬𝐭𝐢𝐭𝐮𝐭𝐞𝐬\r\nAnother core purpose of data use is to facilitate communication. The primary way UniAds enables communication is through institutional content. Institutes can share information via:\r\n● 𝐂𝐨𝐮𝐫𝐬𝐞 𝐥𝐢𝐬𝐭𝐢𝐧𝐠𝐬 with full details of programs offered\r\n● 𝐏𝐨𝐬𝐭𝐬 𝐚𝐧𝐝 𝐚𝐧𝐧𝐨𝐮𝐧𝐜𝐞𝐦𝐞𝐧𝐭𝐬 about new degrees, updates, or changes\r\n● 𝐄𝐯𝐞𝐧𝐭𝐬 to highlight upcoming seminars, workshops, or open days\r\n\r\n𝟒. 𝐀𝐧𝐚𝐥𝐲𝐭𝐢𝐜𝐬 𝐚𝐧𝐝 𝐒𝐞𝐫𝐯𝐢𝐜𝐞 𝐈𝐦𝐩𝐫𝐨𝐯𝐞𝐦𝐞𝐧𝐭𝐬\r\nWe also analyze usage patterns to improve UniAds. For example, by studying which courses or posts are most viewed, we can enhance search accuracy and help institutes understand student interests. Premium institutes receive access to their own analytics dashboards, which highlight engagement trends, post performance, and course application statistics. This insight helps institutes tailor their offerings more effectively.\r\n\r\n𝟓. 𝐒𝐞𝐜𝐮𝐫𝐢𝐭𝐲 𝐚𝐧𝐝 𝐅𝐫𝐚𝐮𝐝 𝐏𝐫𝐞𝐯𝐞𝐧𝐭𝐢𝐨𝐧\r\nLastly, we use certain data points to detect and prevent misuse. Login attempts, payment activity, and unusual account behavior are monitored to protect against fraud and unauthorized access. In cases of policy violations, this information allows us to enforce our Terms of Service and maintain a safe environment for all users. To protect our users and the integrity of UniAds, \r\nwe use information to:\r\n● Detect and block suspicious activity (e.g., multiple failed logins, unusual payment attempts).\r\n● Prevent fraudulent account creation or unauthorized subscription usage.\r\n● Enforce compliance with our 𝐓𝐞𝐫𝐦𝐬 𝐨𝐟 𝐒𝐞𝐫𝐯𝐢𝐜𝐞 and 𝐏𝐫𝐢𝐯𝐚𝐜𝐲 𝐏𝐨𝐥𝐢𝐜𝐲.\r\n● Secure communication between students and institutes.', 3],
            ['HOW WE SHARE YOUR INFORMATION', 'UniAds values your privacy and only shares your information when it is necessary to provide our services, comply with the law, or improve the platform. We never sell your personal data to third parties.\r\n\r\n𝟏. 𝐖𝐢𝐭𝐡 𝐈𝐧𝐬𝐭𝐢𝐭𝐮𝐭𝐞𝐬 (𝐰𝐡𝐞𝐧 𝐚𝐩𝐩𝐥𝐲𝐢𝐧𝐠)\r\nWhen you apply to a course through UniAds, the information you provide such as your name, email, contact number and application details is shared directly with the relevant institution. This ensures institutes receive the details they need to review and process your application. Outside of the application process, your personal details are not disclosed to institutions without your explicit action.\r\n\r\n𝟐. 𝐖𝐢𝐭𝐡 𝐒𝐞𝐫𝐯𝐢𝐜𝐞 𝐏𝐫𝐨𝐯𝐢𝐝𝐞𝐫𝐬 (𝐏𝐚𝐲𝐦𝐞𝐧𝐭 𝐠𝐚𝐭𝐞𝐰𝐚𝐲, 𝐡𝐨𝐬𝐭𝐢𝐧𝐠, 𝐚𝐧𝐚𝐥𝐲𝐭𝐢𝐜𝐬)\r\nWe work with trusted third-party service providers to operate UniAds effectively:\r\n● 𝐏𝐚𝐲𝐦𝐞𝐧𝐭 𝐆𝐚𝐭𝐞𝐰𝐚𝐲: For premium institute subscriptions, we use a payment gateway that is widely accepted in Sri Lanka. This gateway offers advanced security, protecting transactions with state-of-the-art encryption and fraud prevention systems, and complies with PCI DSS 4.0 certification to ensure your financial data is handled safely. UniAds does not store sensitive payment information such as credit or debit card numbers.\r\n● 𝐇𝐨𝐬𝐭𝐢𝐧𝐠 𝐚𝐧𝐝 𝐢𝐧𝐟𝐫𝐚𝐬𝐭𝐫𝐮𝐜𝐭𝐮𝐫𝐞: Our platform runs on secure hosting services that process and store data on our behalf.\r\n● 𝐀𝐧𝐚𝐥𝐲𝐭𝐢𝐜𝐬 𝐭𝐨𝐨𝐥𝐬: We may use analytics services to understand how UniAds is used, so we can improve features and performance. These tools only collect aggregated or anonymized information whenever possible.\r\n\r\n𝟑. 𝐖𝐢𝐭𝐡 𝐀𝐮𝐭𝐡𝐨𝐫𝐢𝐭𝐢𝐞𝐬 𝐖𝐡𝐞𝐧 𝐋𝐞𝐠𝐚𝐥𝐥𝐲 𝐑𝐞𝐪𝐮𝐢𝐫𝐞𝐝\r\nWe may disclose information if required by law, regulation, legal process, or government request. This includes sharing data to comply with court orders, enforce our terms of service, or protect the rights, property, and safety of UniAds, our users, or others.', 4],
            ['LEGAL BASIS FOR PROCESSING', 'UniAds processes personal information only where we have a lawful and legitimate basis to do so. This ensures that your data is handled responsibly, transparently, and in line with data protection regulations. The key legal bases we rely on include:\r\n\r\n● 𝐂𝐨𝐧𝐬𝐞𝐧𝐭: In certain cases, we process your information only after obtaining your clear consent. For example, when you register an account, apply for a course, or choose to share optional details with an institute, you are explicitly agreeing to provide us with that information. You may withdraw consent at any time, though this may limit your ability to use some features of UniAds.\r\n\r\n● 𝐂𝐨𝐧𝐭𝐫𝐚𝐜𝐭𝐮𝐚𝐥 𝐍𝐞𝐜𝐞𝐬𝐬𝐢𝐭𝐲: Many of our services require the processing of your data in order to fulfill a contract with you. This includes managing your account, enabling course applications, providing institute dashboards, and handling premium subscriptions. Without processing this data, UniAds would not be able to deliver the services you expect.\r\n\r\n● 𝐋𝐞𝐠𝐚𝐥 𝐎𝐛𝐥𝐢𝐠𝐚𝐭𝐢𝐨𝐧𝐬: In some situations, we are legally required to process and share information. For instance, we may need to retain payment-related records for auditing or disclose data to authorities if required by law or regulatory compliance in Sri Lanka.\r\n\r\n● 𝐋𝐞𝐠𝐢𝐭𝐢𝐦𝐚𝐭𝐞 𝐈𝐧𝐭𝐞𝐫𝐞𝐬𝐭𝐬: We may process your data when it is necessary for the legitimate interests of UniAds or third parties, provided that these interests are not overridden by your rights and freedoms. Examples include analyzing usage trends to improve our services, preventing fraudulent activity, ensuring platform security, and maintaining reliable operations.\r\n\r\n● 𝐏𝐮𝐛𝐥𝐢𝐜 𝐈𝐧𝐭𝐞𝐫𝐞𝐬𝐭 𝐨𝐫 𝐕𝐢𝐭𝐚𝐥 𝐈𝐧𝐭𝐞𝐫𝐞𝐬𝐭𝐬 (𝐫𝐚𝐫𝐞 𝐜𝐚𝐬𝐞𝐬): Although uncommon, UniAds may process or disclose information where it is necessary to protect vital interests (such as preventing harm or addressing urgent safety concerns) or where processing supports tasks carried out in the public interest, such as cooperating with authorities during investigations.', 5],
            ['DATA RETENTION', 'At UniAds, we only retain data for as long as it is required to operate our services, comply with legal obligations, and protect the platform’s reliability. When data is no longer needed, it is securely deleted or anonymized.\r\n\r\n𝟏. 𝐇𝐨𝐰 𝐥𝐨𝐧𝐠 𝐰𝐞 𝐤𝐞𝐞𝐩 𝐚𝐜𝐜𝐨𝐮𝐧𝐭, 𝐩𝐚𝐲𝐦𝐞𝐧𝐭, 𝐚𝐧𝐝 𝐚𝐜𝐭𝐢𝐯𝐢𝐭𝐲 𝐝𝐚𝐭𝐚\r\n\r\n● 𝐒𝐭𝐮𝐝𝐞𝐧𝐭 𝐀𝐜𝐜𝐨𝐮𝐧𝐭𝐬 (𝐔𝐬𝐞𝐫𝐬): Student account details are stored as long as the account remains active. Students can permanently delete their account at any time through the self-service option. When deleted, all personal information and related activity (applications, reviews, etc.) are erased, except for financial or legal records that must be kept by law.\r\n\r\n● 𝐈𝐧𝐬𝐭𝐢𝐭𝐮𝐭𝐞 𝐀𝐜𝐜𝐨𝐮𝐧𝐭𝐬: Institutes must contact the UniAds administration to request deletion. Once confirmed, the institute’s entire profile, including account details, course listings, and related data, will be 𝐩𝐞𝐫𝐦𝐚𝐧𝐞𝐧𝐭𝐥𝐲 𝐫𝐞𝐦𝐨𝐯𝐞𝐝 from our systems. UniAds will not retain any identifiable institute details after deletion, other than payment or billing records we are legally required to store for financial compliance.\r\n\r\n● 𝐏𝐚𝐲𝐦𝐞𝐧𝐭 𝐚𝐧𝐝 𝐁𝐢𝐥𝐥𝐢𝐧𝐠 𝐈𝐧𝐟𝐨𝐫𝐦𝐚𝐭𝐢𝐨𝐧: Transaction records, invoices, and related billing information are retained in accordance with Sri Lankan financial and tax regulations. This typically requires retention for a minimum of 𝟕 𝐲𝐞𝐚𝐫𝐬, even after a student or institute account is deleted.\r\n\r\n● 𝐀𝐜𝐭𝐢𝐯𝐢𝐭𝐲 𝐃𝐚𝐭𝐚 (𝐏𝐨𝐬𝐭𝐬, 𝐄𝐯𝐞𝐧𝐭𝐬, 𝐑𝐞𝐯𝐢𝐞𝐰𝐬, 𝐀𝐩𝐩𝐥𝐢𝐜𝐚𝐭𝐢𝐨𝐧𝐬): When a student or institute account is deleted, associated content is either permanently removed or anonymized to ensure it cannot be traced back to the user or institute.\r\n\r\n𝟐. 𝐃𝐞𝐥𝐞𝐭𝐢𝐨𝐧 𝐚𝐧𝐝 𝐀𝐧𝐨𝐧𝐲𝐦𝐢𝐳𝐚𝐭𝐢𝐨𝐧 𝐏𝐨𝐥𝐢𝐜𝐲\r\n\r\n● 𝐅𝐨𝐫 𝐒𝐭𝐮𝐝𝐞𝐧𝐭𝐬: A self-service option is provided to delete accounts. Deletion is permanent, and no identifiable information is retained except where required for financial or legal compliance.\r\n\r\n● 𝐅𝐨𝐫 𝐈𝐧𝐬𝐭𝐢𝐭𝐮𝐭𝐞𝐬: Institutes must request deletion through UniAds administration. Once approved, no institute details will be retained, ensuring complete removal of identity and data, except for legally mandated financial records.\r\n\r\n● 𝐀𝐧𝐨𝐧𝐲𝐦𝐢𝐳𝐚𝐭𝐢𝐨𝐧: In cases where some data must be preserved for compliance (e.g., payment records), all identifiable information is stripped to ensure it cannot be linked back to the student or institute.', 6],
            ['DATA SECURITY', 'At UniAds, safeguarding your personal and institutional data is a top priority. We apply multiple layers of technical, administrative, and physical safeguards to ensure that information is stored and transmitted securely.\r\n\r\n𝟏. 𝐌𝐞𝐚𝐬𝐮𝐫𝐞𝐬 𝐖𝐞 𝐓𝐚𝐤𝐞 𝐭𝐨 𝐏𝐫𝐨𝐭𝐞𝐜𝐭 𝐘𝐨𝐮𝐫 𝐃𝐚𝐭𝐚\r\n\r\n● 𝐄𝐧𝐜𝐫𝐲𝐩𝐭𝐢𝐨𝐧: Sensitive information, including login credentials and payment transactions, is encrypted both in transit (when data moves between your device and our servers) and at rest (when stored in our systems).\r\n\r\n● 𝐀𝐜𝐜𝐞𝐬𝐬 𝐂𝐨𝐧𝐭𝐫𝐨𝐥: Only authorized personnel have access to sensitive user or institute data. Internal access is restricted and monitored to prevent unauthorized use.\r\n\r\n● 𝐑𝐞𝐠𝐮𝐥𝐚𝐫 𝐒𝐞𝐜𝐮𝐫𝐢𝐭𝐲 𝐑𝐞𝐯𝐢𝐞𝐰𝐬: Our systems undergo routine audits, vulnerability assessments, and software updates to keep pace with evolving security standards.\r\n\r\n● 𝐒𝐞𝐜𝐮𝐫𝐞 𝐏𝐚𝐲𝐦𝐞𝐧𝐭 𝐏𝐫𝐨𝐜𝐞𝐬𝐬𝐢𝐧𝐠: All payment information is handled through a 𝐏𝐂𝐈 𝐃𝐒𝐒 𝟒.𝟎 𝐜𝐞𝐫𝐭𝐢𝐟𝐢𝐜𝐚𝐭𝐞𝐝 𝐩𝐚𝐲𝐦𝐞𝐧𝐭 𝐠𝐚𝐭𝐞𝐰𝐚𝐲 that uses advanced encryption and fraud prevention mechanisms to protect financial transactions. UniAds itself does not store credit/debit card details.\r\n\r\n● 𝐁𝐚𝐜𝐤𝐮𝐩 𝐚𝐧𝐝 𝐑𝐞𝐜𝐨𝐯𝐞𝐫𝐲: We maintain secure backups and disaster recovery protocols to ensure continuity of service in case of unexpected technical issues.\r\n\r\n𝟐. 𝐀𝐜𝐤𝐧𝐨𝐰𝐥𝐞𝐝𝐠𝐞𝐦𝐞𝐧𝐭 𝐨𝐟 𝐎𝐧𝐥𝐢𝐧𝐞 𝐒𝐞𝐜𝐮𝐫𝐢𝐭𝐲 𝐋𝐢𝐦𝐢𝐭𝐚𝐭𝐢𝐨𝐧𝐬\r\nWhile we are committed to protecting your data, it’s important to recognize that 𝐧𝐨 𝐦𝐞𝐭𝐡𝐨𝐝 𝐨𝐟 𝐨𝐧𝐥𝐢𝐧𝐞 𝐬𝐭𝐨𝐫𝐚𝐠𝐞 𝐨𝐫 𝐭𝐫𝐚𝐧𝐬𝐦𝐢𝐬𝐬𝐢𝐨𝐧 𝐢𝐬 𝟏𝟎𝟎% 𝐬𝐞𝐜𝐮𝐫𝐞. Despite the security measures we employ, risks such as unauthorized access, hacking, or data breaches can never be entirely eliminated.\r\nBy using UniAds, you acknowledge these inherent limitations of online services. We encourage all users and institutes to also take precautionary measures such as using strong passwords, keeping account credentials confidential, and promptly reporting any suspicious activity.', 7],
            ['COOKIES AND TRACKING', 'To improve the functionality, performance, and overall user experience of UniAds, we use cookies and similar tracking technologies. Cookies are small files stored on your device that help us remember your preferences and understand how our platform is used.\r\n\r\n𝟏. 𝐓𝐲𝐩𝐞𝐬 𝐨𝐟 𝐂𝐨𝐨𝐤𝐢𝐞𝐬 𝐖𝐞 𝐔𝐬𝐞\r\n\r\n● 𝐄𝐬𝐬𝐞𝐧𝐭𝐢𝐚𝐥 𝐂𝐨𝐨𝐤𝐢𝐞𝐬: These cookies are strictly necessary for UniAds to function. They allow you to log in securely, navigate between pages, and access protected areas such as institute dashboards. Without them, core features of the platform would not work properly.\r\n\r\n● 𝐀𝐧𝐚𝐥𝐲𝐭𝐢𝐜𝐬 𝐂𝐨𝐨𝐤𝐢𝐞𝐬: Analytics cookies help us understand how students and institutes interact with UniAds. For example, they track which courses are viewed most often, how long users spend on the site, and what devices or browsers are being used. This information is aggregated and anonymized, and it enables us to continuously improve the platform.\r\n\r\n● 𝐏𝐞𝐫𝐟𝐨𝐫𝐦𝐚𝐧𝐜𝐞 𝐂𝐨𝐨𝐤𝐢𝐞𝐬: These cookies measure the effectiveness of certain features and optimize the speed and reliability of UniAds. For example, they may help us test new layouts, track loading times, and ensure a smoother browsing experience.\r\n\r\n𝟐. 𝐔𝐬𝐞𝐫 𝐂𝐡𝐨𝐢𝐜𝐞𝐬 𝐟𝐨𝐫 𝐌𝐚𝐧𝐚𝐠𝐢𝐧𝐠 𝐂𝐨𝐨𝐤𝐢𝐞𝐬\r\nBy continuing to use UniAds without adjusting your cookie settings, you consent to our use of cookies as described following. \r\nYou have control over how cookies are used on UniAds:\r\n● 𝐁𝐫𝐨𝐰𝐬𝐞𝐫 𝐒𝐞𝐭𝐭𝐢𝐧𝐠𝐬: Most web browsers allow you to manage or block cookies through their settings. You can choose to delete existing cookies, disable new ones, or receive alerts when cookies are being set.\r\n● 𝐎𝐩𝐭-𝐎𝐮𝐭 𝐨𝐟 𝐀𝐧𝐚𝐥𝐲𝐭𝐢𝐜𝐬: Some analytics services we use provide their own opt-out mechanisms if you prefer not to be tracked.\r\n● 𝐈𝐦𝐩𝐚𝐜𝐭 𝐨𝐟 𝐃𝐢𝐬𝐚𝐛𝐥𝐢𝐧𝐠 𝐂𝐨𝐨𝐤𝐢𝐞𝐬: Please note that if you disable or block essential cookies, some parts of UniAds may not work properly. Features such as logging into your account, applying to institutes, or saving preferences may be limited.', 8],
            ['YOUR RIGHTS', 'At UniAds, we respect your privacy and are committed to giving you control over your personal information. As a user, you have the right to access the personal data we hold about you. This means you can request a copy of the information associated with your account, including registration details, activity logs, and any interactions you have had with institutes. You can also update or correct any inaccuracies in your personal data to ensure it is current and accurate.\r\n\r\nIn situations where you have provided consent for specific processing activities, you have the right to withdraw that consent at any time. For example, if you previously agreed to receive notifications about new courses or promotional updates, you can opt out and stop future communications related to that consent. However, withdrawing consent does not affect the lawfulness of processing based on prior consent or other legal bases.\r\n\r\nTo exercise these rights, users can typically access their account settings to make updates or initiate deletions. Students who wish to delete their accounts can do so directly from the platform. Institutes, on the other hand, must contact the UniAds administration team to request deletion or other changes to their account data. All requests are handled promptly in accordance with applicable data protection laws, and we strive to respond to all user requests efficiently and transparently.', 9],
            ['CHANGES & CONTACT', 'UniAds may update this Privacy Policy periodically to reflect changes in our services, practices, or legal requirements. Users and institutes are encouraged to review this page regularly to stay informed. Significant updates will be communicated clearly, while minor updates will be reflected directly on the website.\r\n\r\n𝐇𝐨𝐰 𝐰𝐞 𝐜𝐨𝐦𝐦𝐮𝐧𝐢𝐜𝐚𝐭𝐞 𝐩𝐨𝐥𝐢𝐜𝐲 𝐮𝐩𝐝𝐚𝐭𝐞𝐬:\r\n● Major changes to the Privacy Policy will be notified on the UniAds website.\r\n● Users should check this page periodically to stay informed of the latest practices.\r\n● Minor modifications may not trigger direct notifications but are effective immediately upon posting.\r\n\r\n𝐂𝐨𝐧𝐭𝐚𝐜𝐭 𝐝𝐞𝐭𝐚𝐢𝐥𝐬 𝐟𝐨𝐫 𝐩𝐫𝐢𝐯𝐚𝐜𝐲 𝐢𝐧𝐪𝐮𝐢𝐫𝐢𝐞𝐬:\r\n● 𝐄𝐦𝐚𝐢𝐥: support@uniads.lk\r\n● 𝐇𝐨𝐭𝐥𝐢𝐧𝐞: +94772300279\r\n● 𝐂𝐨𝐧𝐭𝐚𝐜𝐭 𝐨𝐧 𝐖𝐡𝐚𝐭𝐬𝐀𝐩𝐩: +94772300279\r\n● 𝐏𝐨𝐬𝐭𝐚𝐥 𝐀𝐝𝐝𝐫𝐞𝐬𝐬: [Insert Complete Physical Address of UniAds Headquarters]\r\n\r\nWe are committed to addressing all privacy-related questions and concerns promptly. Users and institutes can contact us using the above channels to:\r\n● Request information about how their data is used\r\n● Seek guidance regarding privacy rights\r\n● Report issues or request corrections', 10],
        ];

        foreach ($sections as $section) {
            DB::table('privacy_policy')->insert([
                'title' => $section[0],
                'content' => $section[1],
                'order_index' => $section[2],
                'created_at' => now(),
                'updated_at' => now(),
            ]);
        }
    }
}
